{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, the closest structural analogue sharing the sulfamoyl-chloro-benzamide/quinazolinone core and N-aryl substitution, has approximately 100% absolute oral bioavailability in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Valdecoxib, a sulfonamide-containing drug with high assay transfer, has an absolute oral bioavailability of 83% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Meloxicam, an acidic sulfonamide-containing drug, has an absolute oral bioavailability of 91% in healthy fasting volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ixazomib, a polar boronic acid drug, has an absolute oral bioavailability of 58% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "PF-05241328, the lowest measured analogue, still has an absolute oral bioavailability of 38%, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Celecoxib, despite poor aqueous solubility, has an oral bioavailability of 20–40%, which meets the F≥20% threshold and therefore supports high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence supports high oral bioavailability: the closest analogue metolazone is ~100% bioavailable, and other sulfonamide/acidic drugs (valdecoxib 83%, meloxicam 91%, ixazomib 58%, PF-05241328 38%, celecoxib 20–40%) all meet or exceed the 20% threshold. The query is therefore predicted high.",
  "evidence_gaps": [
    "No direct experimental F value for the query molecule itself is included; prediction relies on transferable analogues.",
    "Some records report bioavailability qualitatively or with unspecified absolute method, but key analogues have absolute F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

